def move_price_stock_to_variants(apps, schema_editor):
    """Preserve existing data: each old product becomes one live/inactive product with one default variant."""
    Product = apps.get_model('catalog', 'Product')
    Variant = apps.get_model('catalog', 'ProductVariant')
    for p in Product.objects.all():
        p.status = 'live' if p.is_active else 'inactive'
        p.save(update_fields=['status'])
        Variant.objects.create(
            product=p, seller_id=p.seller_id, label='Default', sku=(p.sku or f'P{p.pk}')[:40],
            mrp=p.price, price=p.price, stock=p.stock,
        )


